static void show_status(void){char text[256];snprintf(text,sizeof(text),"%u shown / %u packages • %u requested / %u automatic changes • queued changes • %s theme%s",visible,eina_array_count(packages),marked_count(),eina_hash_population(automatic),safe_theme?"standard":"system EFL",catalog_warning&&*catalog_warning?" • partial Flatpak metadata":"");label(status,text);if(catalog_warning&&*catalog_warning)elm_object_tooltip_text_set(status,catalog_warning);else elm_object_tooltip_unset(status);}
static void request_clear(Request *r){if(r->input_file){unlink(r->input_file);free(r->input_file);r->input_file=NULL;}if(r->out)eina_strbuf_free(r->out);if(r->err)eina_strbuf_free(r->err);r->out=r->err=NULL;r->exe=NULL;}
