static Eina_Bool populate_rows(void *data){(void)data;unsigned count=eina_array_count(packages),limit=cursor+250;if(limit>count)limit=count;for(;cursor<limit;cursor++){Package *p=eina_array_data_get(packages,cursor);if(matches(p)){p->item=elm_genlist_item_append(list,row_class,p,NULL,ELM_GENLIST_ITEM_NONE,selected,p);visible++;}}show_status();if(cursor==count){populate=NULL;return ECORE_CALLBACK_CANCEL;}return ECORE_CALLBACK_RENEW;}
